import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"Tensor","link":"/api/SIMD-API/tensor_api/tensor/tensor_structure"},{"text":"pointer","link":"/api/SIMD-API/tensor_api/tensor/pointer"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/tensor/pointer.md","filePath":"api/SIMD-API/tensor_api/tensor/pointer.md","outlineHeaders":[{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787967772000}'),c={name:"api/SIMD-API/tensor_api/tensor/pointer.md"};function e(t,s,o,i,r,_){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>pointer</h1><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>Tensor API通过<code>make_mem_ptr</code>构造带物理存储位置信息的指针适配器。指针适配器保留原始指针或迭代器的访问能力，并通过<code>ptr_pattern</code>标记Global Memory、L1 Buffer、L0A Buffer等物理位置。使用时只需调用对外接口<code>make_mem_ptr</code>，不需要直接构造内部指针适配器类型。</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>原始指针必须指向有效的内存空间。</li><li>指定的<code>location</code>必须与实际物理存储位置一致。</li><li>指针适配器的数据类型必须与实际数据类型一致。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/tensor.h&quot;</span>

<span class="k">using</span><span class="w"> </span><span class="k">namespace</span><span class="w"> </span><span class="nn">asc</span><span class="o">::</span><span class="nn">te</span><span class="p">;</span>

<span class="k">constexpr</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">size</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">256</span><span class="p">;</span>
<span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">ub_data</span><span class="p">[</span><span class="n">size</span><span class="p">];</span>
<span class="n">__cbuf__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">l1_data</span><span class="p">[</span><span class="n">size</span><span class="p">];</span>
<span class="n">__ca__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">l0a_data</span><span class="p">[</span><span class="n">size</span><span class="p">];</span>

<span class="c1">// 创建Unified Buffer（UB）指针</span>
<span class="k">auto</span><span class="w"> </span><span class="n">ub_ptr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">ub_data</span><span class="p">);</span>

<span class="c1">// 创建L1 Buffer指针</span>
<span class="k">auto</span><span class="w"> </span><span class="n">l1_ptr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">l1_data</span><span class="p">);</span>

<span class="c1">// 创建L0A Buffer指针</span>
<span class="k">auto</span><span class="w"> </span><span class="n">ca_ptr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">l0a_data</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const u=a(c,[["render",e]]);export{h as __pageData,u as default};
